package org.apache.commons.lang3.time;

import java.io.*;
import java.math.*;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DateUtils_isSameDay_TriageGen2Test {









    @Test
    public void testIsSameDay_DifferentEra() {
        // Testing ERA branch: BC vs AD
        // Using a very old date to trigger different ERA
        Calendar cal1 = new GregorianCalendar(1, Calendar.JANUARY, 1); // Year 1 AD
        Calendar cal2 = new GregorianCalendar(-1, Calendar.JANUARY, 1); // Year 1 BC (approx)

        // Note: GregorianCalendar handling of BC can be tricky, 
        // but the logic in the method specifically checks cal1.get(Calendar.ERA) == cal2.get(Calendar.ERA)
        // We ensure they are different eras.
        assertFalse("Expected false for different Eras", DateUtils.isSameDay(cal1, cal2));
    }






}

